using namespace std;
static uint64_t nowms(){timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return (uint64_t)ts.tv_sec*1000+ts.tv_nsec/1000000;}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r\n"),b=s.find_last_not_of(" \t\r\n");return a==string::npos?string():s.substr(a,b-a+1);}
static bool number(const string&s,uint64_t&v){if(s.empty())return false;v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(UINT64_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return true;}
static bool token(unsigned char c){return(c>='0'&&c<='9')||(c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c&&strchr("!#$%&'*+-.^_`|~",c));}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;unsigned n;uint32_t cp;if(c>=0xc2&&c<=0xdf){n=1;cp=c&31;}else if(c>=0xe0&&c<=0xef){n=2;cp=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;cp=c&7;}else return false;if(i+n>s.size())return false;for(unsigned j=0;j<n;j++){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;cp=(cp<<6)|(d&63);}if((n==2&&cp<0x800)||(n==3&&cp<0x10000)||(cp>=0xd800&&cp<=0xdfff)||cp>0x10ffff)return false;}return true;}
static int hexval(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
struct Config{string ip,root;int port=0;uint64_t maxconn=0,headers=0,ht=0,idle=0,wt=0,requests=0,pipeline=0;}cfg;
static bool config(const char*path){ifstream f(path);if(!f)return false;unordered_map<string,string>m;string line;while(getline(f,line)){if(line.find('\0')!=string::npos||!utf8(line))return false;line=trim(line);if(line.empty()||line[0]=='#')continue;auto p=line.find('=');if(p==string::npos)return false;string k=trim(line.substr(0,p)),v=trim(line.substr(p+1));if(k.empty()||v.empty()||m.count(k))return false;m[k]=v;}if(f.bad()||m.size()!=9)return false;const char*keys[]={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth"};for(auto k:keys)if(!m.count(k))return false;auto pos=m["listen"].rfind(':');if(pos==string::npos)return false;cfg.ip=m["listen"].substr(0,pos);uint64_t port;in_addr addr;if(!number(m["listen"].substr(pos+1),port)||port==0||port>65535||inet_pton(AF_INET,cfg.ip.c_str(),&addr)!=1)return false;cfg.port=port;cfg.root=m["root"];if(cfg.root.empty()||cfg.root[0]!='/')return false;struct stat st;if(stat(cfg.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;uint64_t*vals[]={&cfg.maxconn,&cfg.headers,&cfg.ht,&cfg.idle,&cfg.wt,&cfg.requests,&cfg.pipeline};for(int i=0;i<7;i++)if(!number(m[keys[i+2]],*vals[i])||!*vals[i])return false;return true;}
struct Conn{int fd=-1,file=-1;uint64_t serial=0,deadline=0;string input,out;size_t outpos=0;off_t offset=0;uint64_t remaining=0;bool writing=false,registered=false;};
struct Timer{uint64_t at,id;int fd;bool operator<(const Timer&o)const{return at>o.at;}};static priority_queue<Timer>timers;static vector<Conn*>conns;static uint64_t serial=0;static int ep=-1,rootfd=-1;static size_t active=0;
static void drop(Conn*c){int fd=c->fd;if(c->registered)epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);if(c->file>=0)close(c->file);conns[fd]=nullptr;delete c;--active;}
static void deadline(Conn*c,uint64_t ms){uint64_t now=nowms();c->deadline=ms>UINT64_MAX-now?UINT64_MAX:now+ms;timers.push({c->deadline,c->serial,c->fd});}
static void response(Conn*c,int code,int file=-1,uint64_t size=0){const char*reason=code==200?"OK":code==400?"Bad Request":code==403?"Forbidden":code==404?"Not Found":code==405?"Method Not Allowed":code==431?"Request Header Fields Too Large":"Internal Server Error";if(code!=200){size=0;if(file>=0)close(file);file=-1;}c->file=file;c->remaining=size;c->out="HTTP/1.1 "+to_string(code)+" "+reason+"\r\nContent-Length: "+to_string(size)+"\r\nConnection: close\r\n"+(code==200?"Content-Type: application/octet-stream\r\n":"")+"\r\n";c->outpos=0;c->writing=true;c->input.clear();deadline(c,cfg.wt);}
static int fileopen(const string&path,int&out,uint64_t&size){vector<string>comp;size_t p=1;while(p<=path.size()){size_t q=path.find('/',p);if(q==string::npos)q=path.size();string s=path.substr(p,q-p);if(s=="..")return 403;if(!s.empty())comp.push_back(s);p=q+1;if(q==path.size())break;}if(comp.empty())return 403;int dir=rootfd;for(size_t i=0;i<comp.size();i++){bool last=i+1==comp.size();int fd=openat(dir,comp[i].c_str(),(last?O_RDONLY|O_NONBLOCK:O_PATH)|O_CLOEXEC|O_NOFOLLOW);int e=errno;if(dir!=rootfd)close(dir);if(fd<0){if(e==ENOENT||e==ENOTDIR)return 404;return 403;}struct stat st;if(fstat(fd,&st)){close(fd);return 403;}if(S_ISLNK(st.st_mode)){close(fd);return 403;}if(last){if(!S_ISREG(st.st_mode)||path.back()=='/'){close(fd);return 403;}out=fd;size=st.st_size;return 200;}if(!S_ISDIR(st.st_mode)){close(fd);return 403;}dir=fd;}if(dir!=rootfd)close(dir);return 403;}
static void parse(Conn*c){const string&s=c->input;size_t end=s.find("\r\n\r\n");if(end==string::npos)return;if(end+4>cfg.headers){response(c,431);return;}size_t line=s.find("\r\n");if(line==string::npos||line==0){response(c,400);return;}string req=s.substr(0,line);size_t a=req.find(' '),b=a==string::npos?string::npos:req.find(' ',a+1);if(a==string::npos||a==0||b==string::npos||b==a+1||req.find(' ',b+1)!=string::npos){response(c,400);return;}string method=req.substr(0,a),target=req.substr(a+1,b-a-1),version=req.substr(b+1);for(unsigned char ch:method)if(!token(ch)){response(c,400);return;}if(version!="HTTP/1.0"&&version!="HTTP/1.1"){response(c,400);return;}if(target.empty()||target[0]!='/'||target.find('#')!=string::npos||target.find('\\')!=string::npos){response(c,400);return;}for(unsigned char ch:target)if(ch<=32||ch==127){response(c,400);return;}bool cl=false;size_t p=line+2;while(p<end){size_t q=s.find("\r\n",p);if(q==string::npos||q>end||q==p){response(c,400);return;}size_t colon=s.find(':',p);if(colon==string::npos||colon>=q||colon==p){response(c,400);return;}string name;for(size_t i=p;i<colon;i++){unsigned char ch=s[i];if(!token(ch)){response(c,400);return;}name.push_back(ch>='A'&&ch<='Z'?ch+32:ch);}for(size_t i=colon+1;i<q;i++){unsigned char ch=s[i];if((ch<32&&ch!='\t')||ch==127){response(c,400);return;}}string val=s.substr(colon+1,q-colon-1);size_t start=val.find_first_not_of(" \t"),stop=val.find_last_not_of(" \t");val=start==string::npos?"":val.substr(start,stop-start+1);if(name=="transfer-encoding"){response(c,400);return;}if(name=="content-length"){if(cl||val.empty()){response(c,400);return;}cl=true;for(char ch:val)if(ch!='0'){response(c,400);return;}}p=q+2;}size_t qe=target.find('?');string raw=target.substr(0,qe),path;path.reserve(raw.size());for(size_t i=0;i<raw.size();i++){unsigned char ch=raw[i];if(ch=='%'){if(i+2>=raw.size()||hexval(raw[i+1])<0||hexval(raw[i+2])<0){response(c,400);return;}ch=(hexval(raw[i+1])<<4)|hexval(raw[i+2]);i+=2;}if(ch==0||ch=='\\'){response(c,400);return;}path.push_back(ch);}if(!utf8(path)){response(c,400);return;}if(method!="GET"){response(c,405);return;}int fd=-1;uint64_t n=0;int status=fileopen(path,fd,n);response(c,status,fd,n);}
static void readconn(Conn*c){char buf[16384];for(;;){if(nowms()>=c->deadline){drop(c);return;}ssize_t n=recv(c->fd,buf,sizeof(buf),0);if(n>0){size_t old=c->input.size();c->input.append(buf,n);size_t stop=c->input.find("\r\n\r\n",old>=3?old-3:0);size_t check=stop==string::npos?c->input.size():stop+4;for(size_t i=old?old-1:0;i<check;i++){char ch=c->input[i];if(ch=='\0'||(ch=='\n'&&(i==0||c->input[i-1]!='\r'))||(ch=='\r'&&i+1<check&&c->input[i+1]!='\n')){response(c,400);return;}}if(stop!=string::npos){parse(c);return;}if(c->input.size()>cfg.headers){response(c,431);return;}continue;}if(n==0){drop(c);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return;drop(c);return;}}
static bool writeconn(Conn*c){while(c->outpos<c->out.size()){if(nowms()>=c->deadline){drop(c);return true;}ssize_t n=send(c->fd,c->out.data()+c->outpos,c->out.size()-c->outpos,MSG_NOSIGNAL|(c->remaining?MSG_MORE:0));if(n>0){c->outpos+=n;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return false;drop(c);return true;}size_t sent=0;while(c->remaining){if(nowms()>=c->deadline){drop(c);return true;}if(sent>=1048576)return false;ssize_t n=sendfile(c->fd,c->file,&c->offset,(size_t)min<uint64_t>(c->remaining,1048576-sent));if(n>0){c->remaining-=n;sent+=n;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return false;drop(c);return true;}drop(c);return true;}
static void handle(Conn*c,uint32_t event){int fd=c->fd;uint64_t sid=c->serial;if(nowms()>=c->deadline){drop(c);return;}if(!c->writing)readconn(c);c=conns[fd];if(!c||c->serial!=sid)return;if(c->writing){if(writeconn(c))return;}else if(event&(EPOLLERR|EPOLLHUP|EPOLLRDHUP)){drop(c);return;}epoll_event e{};e.events=(c->writing?EPOLLOUT:EPOLLIN)|EPOLLRDHUP;e.data.u64=(sid<<16)|(unsigned)fd;int op=c->registered?EPOLL_CTL_MOD:EPOLL_CTL_ADD;if(epoll_ctl(ep,op,fd,&e)){drop(c);return;}c->registered=true;}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||string(argv[1])!="--config"||!config(argv[2]))return 1;rootfd=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return 1;int listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons(cfg.port);inet_pton(AF_INET,cfg.ip.c_str(),&addr.sin_addr);if(bind(listener,(sockaddr*)&addr,sizeof(addr))||listen(listener,16384))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;epoll_event ev{};ev.events=EPOLLIN;ev.data.u64=0;if(epoll_ctl(ep,EPOLL_CTL_ADD,listener,&ev))return 1;conns.resize(16384,nullptr);epoll_event events[512];for(;;){if(timers.size()>active*4+1024){priority_queue<Timer>fresh;for(Conn*c:conns)if(c)fresh.push({c->deadline,c->serial,c->fd});timers.swap(fresh);}uint64_t now=nowms();while(!timers.empty()&&timers.top().at<=now){auto t=timers.top();timers.pop();if(t.fd>=0&&(size_t)t.fd<conns.size()){Conn*c=conns[t.fd];if(c&&c->serial==t.id&&c->deadline==t.at)drop(c);}}int timeout=timers.empty()?-1:(int)min<uint64_t>(timers.top().at>now?timers.top().at-now:0,INT_MAX);int n=epoll_wait(ep,events,512,timeout);if(n<0){if(errno==EINTR)continue;return 1;}for(int i=0;i<n;i++){uint64_t id=events[i].data.u64;if(!id){for(int j=0;j<128;j++){int fd=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR){--j;continue;}break;}if(active>=cfg.maxconn||fd>=(int)conns.size()){close(fd);continue;}Conn*c=new Conn;c->fd=fd;c->serial=++serial;conns[fd]=c;++active;deadline(c,cfg.ht);handle(c,0);}continue;}int fd=id&65535;uint64_t sid=id>>16;if(fd>=(int)conns.size())continue;Conn*c=conns[fd];if(!c||c->serial!=sid)continue;handle(c,events[i].events);}}}
